:root {
  --bg: #2b2b3c;
  --card-bg: #f4f4f8;
  --text: #1e1e2f;
  --accent: #e06c75;
  --accent-hover: #c55a62;
  --accent-pressed: #a84a52;
  --border: #1e1e2f;
  --focus: #61afef;
  --radius: 0px;
  --space: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  padding: calc(var(--space) * 2);
  width: 100%;
  max-width: 720px;
  box-shadow: 8px 8px 0 var(--border);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: var(--space);
  text-transform: uppercase;
  letter-spacing: 2px;
  border-bottom: 3px solid var(--border);
  padding-bottom: 8px;
}

.line-items {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: var(--space);
}

.line-item {
  display: grid;
  grid-template-columns: 1fr 80px 100px 100px auto;
  gap: 8px;
  align-items: center;
  padding: 8px;
  border: 2px solid var(--border);
  background: #fff;
}

.line-item input {
  width: 100%;
  padding: 8px;
  font-size: 1rem;
  border: 2px solid var(--border);
  background: var(--card-bg);
  font-family: inherit;
}

.line-item input:focus {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}

.line-total {
  font-weight: bold;
  text-align: right;
  padding-right: 4px;
}

.btn {
  background: var(--accent);
  color: #fff;
  border: 3px solid var(--border);
  padding: 10px 16px;
  font-size: 1rem;
  font-family: inherit;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, transform 0.05s;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:active {
  background: var(--accent-pressed);
  transform: translate(2px, 2px);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn.remove {
  background: #fff;
  color: var(--border);
  padding: 4px 8px;
  font-size: 0.875rem;
}

.btn.remove:hover {
  background: #eee;
}

.tax-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: var(--space) 0;
  padding: 8px;
  border: 2px solid var(--border);
  background: #fff;
}

.tax-row label {
  font-weight: bold;
}

.tax-row input {
  width: 100px;
  padding: 8px;
  font-size: 1rem;
  border: 2px solid var(--border);
  background: var(--card-bg);
  font-family: inherit;
}

.tax-row input:focus {
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}

.help {
  font-size: 0.875rem;
  color: #555;
  width: 100%;
}

.totals {
  border-top: 3px solid var(--border);
  padding-top: var(--space);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.total-row {
  display: flex;
  justify-content: space-between;
  font-size: 1.125rem;
}

.total-row.grand {
  font-size: 1.375rem;
  font-weight: bold;
  border-top: 2px dashed var(--border);
  padding-top: 8px;
}

@media (max-width: 600px) {
  .line-item {
    grid-template-columns: 1fr 1fr;
  }
  .line-item .line-total {
    grid-column: span 2;
    text-align: left;
  }
  .line-item .btn.remove {
    grid-column: span 2;
    justify-self: start;
  }
}

@media (max-width: 360px) {
  .card {
    padding: var(--space);
  }
  h1 {
    font-size: 1.5rem;
  }
  .line-item {
    grid-template-columns: 1fr;
  }
  .line-item .line-total {
    grid-column: span 1;
  }
  .line-item .btn.remove {
    grid-column: span 1;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const lineItemsContainer = document.getElementById('line-items');
  const addButton = document.getElementById('add-item');
  const taxRateInput = document.getElementById('tax-rate');
  const subtotalEl = document.getElementById('subtotal');
  const taxEl = document.getElementById('tax');
  const grandTotalEl = document.getElementById('grand-total');

  function addLineItem() {
    const item = document.createElement('div');
    item.className = 'line-item';
    item.setAttribute('role', 'listitem');

    const descId = 'desc-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5);
    const qtyId = 'qty-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5);
    const priceId = 'price-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5);

    item.innerHTML = `
      <input type="text" id="${descId}" placeholder="Description" aria-label="Item description" value="">
      <input type="number" id="${qtyId}" min="1" step="1" value="1" aria-label="Quantity">
      <input type="number" id="${priceId}" min="0" step="0.01" value="0.00" aria-label="Unit price">
      <span class="line-total" aria-label="Line total">$0.00</span>
      <button type="button" class="btn remove" aria-label="Remove item">×</button>
    `;

    lineItemsContainer.appendChild(item);

    const descInput = item.querySelector(`#${descId}`);
    const qtyInput = item.querySelector(`#${qtyId}`);
    const priceInput = item.querySelector(`#${priceId}`);
    const lineTotalEl = item.querySelector('.line-total');
    const removeBtn = item.querySelector('.remove');

    function updateLineTotal() {
      const qty = parseFloat(qtyInput.value) || 0;
      const price = parseFloat(priceInput.value) || 0;
      const total = qty * price;
      lineTotalEl.textContent = '$' + total.toFixed(2);
      updateTotals();
    }

    qtyInput.addEventListener('input', updateLineTotal);
    priceInput.addEventListener('input', updateLineTotal);

    removeBtn.addEventListener('click', () => {
      item.remove();
      updateTotals();
    });

    updateLineTotal();
  }

  function updateTotals() {
    let subtotal = 0;
    document.querySelectorAll('.line-item').forEach(item => {
      const qty = parseFloat(item.querySelector('input[type="number"]:nth-of-type(1)').value) || 0;
      const price = parseFloat(item.querySelector('input[type="number"]:nth-of-type(2)').value) || 0;
      subtotal += qty * price;
    });

    const taxRate = parseFloat(taxRateInput.value) || 0;
    const tax = subtotal * (taxRate / 100);
    const grandTotal = subtotal + tax;

    subtotalEl.textContent = '$' + subtotal.toFixed(2);
    taxEl.textContent = '$' + tax.toFixed(2);
    grandTotalEl.textContent = '$' + grandTotal.toFixed(2);
  }

  addButton.addEventListener('click', addLineItem);
  taxRateInput.addEventListener('input', updateTotals);

  // Add one initial line item
  addLineItem();
});
